1	import { getTrueFalseQuestionLimit, selectQuestionsForQuiz } from './quizRules.ts';
2	
3	type Question = {
4	  type: 'mc' | 'mc_multi' | 'tf' | 'match';
5	  label: string;
6	};
7	
8	function mc(label: string): Question {
9	  return { type: 'mc', label };
10	}
11	
12	function tf(label: string): Question {
13	  return { type: 'tf', label };
14	}
15	
16	function assertEquals<T>(actual: T, expected: T, label?: string) {
17	  const a = JSON.stringify(actual);
18	  const b = JSON.stringify(expected);
19	  if (a !== b) {
20	    throw new Error(`${label ? label + ': ' : ''}expected ${b}, got ${a}`);
21	  }
22	}
23	
24	Deno.test('getTrueFalseQuestionLimit: allows one tf per full ten questions', () => {
